1	"use server";
2	
3	/**
4	 * Free Minecraft servers — one per verified account, running as a Docker
5	 * container on the dedicated "freemc-host" VM behind itzg/mc-router (hostname
6	 * -based routing + auto-scale up/down on connect/idle — see FreeMinecraftServer
7	 * in prisma/schema.prisma for the full architecture note).
8	 *
9	 * KNOWN GAP: disk usage is NOT hard-quota-enforced yet (Docker's storage-opt
10	 * quota needs XFS+pquota, which this host's filesystem doesn't have). The RAM
11	 * cap (Docker --memory, a real hard ceiling) and the total-server-count cap are
12	 * the enforced safety controls for now; `free_minecraft_disk_mb` exists for a
13	 * future periodic `du`-based sweep, not wired to anything yet.
14	 */
15	import { revalidatePath } from "next/cache";
16	import { db } from "./db";
17	import { requireUser } from "./auth";
18	import { assertEmailVerified } from "./email-verification";
19	import { checkRateLimit } from "./rate-limit";
20	import { getSettingBool, getSettingInt, getSetting } from "./settings";
21	import { withServerSsh, exec, shellQuote } from "./ssh-exec";
22	import type { SftpServer } from "./sftp";
23	import { validateRconCommand } from "./game-control";
24	import { schemaFor, validateConfig } from "./game-config";
25	import {
26	  rconPasswordFor,
27	  getFreeServerStatus,
28	  getFreeServerPlayers,
29	  sendRcon,
30	  readServerProperties,
31	  writeServerProperties,
32	  liveRconCommandFor,
33	  propertiesToEnv,
34	  FREEMC_PRESETS,
35	  FREEMC_PLUGIN_MC_VERSION,
36	} from "./free-minecraft-control";
37	
38	type Result = { error?: string };
39	
40	const SUBDOMAIN_RE = /^[a-z0-9]([a-z0-9-]{1,18}[a-z0-9])?$/;
41	const RESERVED = new Set(["www", "api", "admin", "mc", "play", "test", "server", "router"]);
42	
43	/** The dedicated Docker host — a real Server row (Server.hostname="freemc-host"),
44	 *  not a customer VPS. Reused via the same withServerSsh every game/backup
45	 *  action already uses; this just points it at our own internal box instead. */
46	async function freemcHost(): Promise<SftpServer> {
47	  const host = await db.server.findFirst({
48	    where: { hostname: "freemc-host" },
49	    select: { id: true, rootPassword: true, rootPasswordEnc: true, sshPort: true, dedicatedIp: { select: { address: true } } },
50	  });
51	  if (!host) throw new Error("Free Minecraft host is not provisioned.");
52	  return host;
53	}
