import { PrismaClient } from "@prisma/client";
const db = new PrismaClient();
const host = await db.server.findFirst({ where: { hostname: "freemc-host" } });
console.log(JSON.stringify(host, (k,v) => typeof v === "bigint" ? v.toString() : v, 2));
await db.$disconnect();

/**
 * Throwaway live-test script for the freemc mod-menu catalog research.
 * Boots a bare PAPER 26.1.2 container named mc-modtest on freemc-host with a
 * candidate set of MODRINTH_PROJECTS layered on, waits, and dumps logs +
 * running state. Deleted before this task finishes.
 */
import { db } from "./lib/db";
import { withServerSsh, exec, shellQuote } from "./lib/ssh-exec";
import type { SftpServer } from "./lib/sftp";

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

async function freemcHost(): Promise<SftpServer> {
  const host = await db.server.findFirst({
    where: { hostname: "freemc-host" },
    select: { id: true, rootPassword: true, rootPasswordEnc: true, sshPort: true, dedicatedIp: { select: { address: true } } },
  });
  if (!host) throw new Error("freemc-host not found");
  return host as unknown as SftpServer;
}

const PROJECTS = process.argv[2];
if (!PROJECTS) {
  console.error("usage: tsx scratch-modtest.ts <comma-separated-modrinth-slugs> [waitSeconds]");
  process.exit(1);
}
const waitSec = Number(process.argv[3] ?? 90);

async function main() {
  const host = await freemcHost();
  await withServerSsh(host, async (conn) => {
    console.log("== connected to freemc-host ==");
    await exec(conn, `docker rm -f mc-modtest`, 30_000);
    await exec(conn, `rm -rf /opt/freemc/modtest && mkdir -p /opt/freemc/modtest`, 15_000);

    const cmd = [
      "docker run -d",
      `--name mc-modtest`,
      "--network freemc",
      `--memory=1536m --memory-swap=1536m --cpus=1`,
      `-v /opt/freemc/modtest:/data`,
      `-e EULA=TRUE -e TYPE=PAPER -e ONLINE_MODE=FALSE`,
      `-e VERSION=${shellQuote("26.1.2")}`,
      `-e MEMORY=1075m`,
      `-e ENABLE_RCON=true -e RCON_PASSWORD=modtestpw123`,
      `-e MODRINTH_PROJECTS=${shellQuote(PROJECTS)}`,
      "itzg/minecraft-server",
    ].join(" ");
    console.log("== docker run ==\n", cmd);
    const run = await exec(conn, cmd, 90_000);
    console.log("run code:", run.code, "stdout:", run.stdout.trim(), "stderr:", run.stderr.trim());

    console.log(`== waiting ${waitSec}s ==`);
    await sleep(waitSec * 1000);

    const check = await exec(conn, `docker inspect -f 'Running={{.State.Running}}'  mc-modtest`, 10_000);
    console.log("== inspect ==", check.stdout.trim(), check.stderr.trim());

    const logs = await exec(conn, `docker logs mc-modtest --tail 200`, 20_000);
    console.log("== logs (tail 200) ==\n", logs.stdout, logs.stderr);
  });
}

main()
  .then(() => process.exit(0))
  .catch((e) => {
    console.error("FAILED", e);
    process.exit(1);
  });

