/**
 * The Mod Menu's curated, vetted catalog of EXTRA Modrinth plugins an owner
 * can layer on top of their active preset's own bundle (see
 * lib/actions-freemc-mods.ts). Deliberately NOT free-text: a plugin slug here
 * is code that runs on our infrastructure via MODRINTH_PROJECTS at
 * container-creation time, so only ever install from this fixed allowlist.
 *
 * Every slug below was picked from a Modrinth search, cross-checked against
 * its /version endpoint for a build whose game_versions includes "26.1.2"
 * AND whose loaders includes "paper" (the same pin every plugins-kind preset
 * uses — see FREEMC_PLUGIN_MC_VERSION in lib/free-minecraft-control.ts), and
 * then LIVE-BOOTED on freemc-host in a throwaway `mc-modtest` PAPER 26.1.2
 * container to confirm a clean load with no plugin-init errors — API
 * metadata alone was NOT trusted (a real failure this session hit: a plugin
 * whose latest Modrinth build only ships "alpha"-labeled versions, which
 * itzg's installer refuses by default even though the version technically
 * lists 26.1.2/paper support).
 *
 * DROPPED after live-testing (kept here as a record so nobody re-adds them
 * without re-solving the same problem):
 *   - grimac (Grim Anticheat): itzg's MODRINTH_PROJECTS installer only
 *     accepts "release"-type versions by default; every one of Grim's
 *     published 26.1.2/paper builds is version-type "alpha", so the install
 *     step itself fails and takes the WHOLE container down with it (verified
 *     live — a single bad slug in the list aborts the entire boot, not just
 *     that one plugin).
 *   - auction-house-plugin (Auction House Plugin): loads fine but hard-fails
 *     at plugin-enable with `UnknownDependencyException: [Vault]` — Vault
 *     isn't in this catalog (it's an economy API bridge with nothing to
 *     bridge to on a stock preset), so this plugin can never actually start.
 *   - crazyauctions (CrazyAuctions): same story as AuctionHouse — needs
 *     Vault. Unlike AuctionHouse it fails soft (logs "Vault was not found,
 *     disabling" and the container stays up), but it would install and do
 *     nothing, so it's excluded as dead weight rather than a working option.
 *
 * Never duplicates a slug any FREEMC_PRESETS entry already bundles:
 * essentialsx, luckperms, vaultunlocked, towny, iridiumskyblock, lifestealz,
 * worldedit, nochatreports-spigot-paper, hungergames-sb, the ajParkour/Prison
 * Spiget resources, or MissileWars.
 */
export type FreeMcModCategory = "Economy" | "Protection" | "Utility" | "Fun" | "Admin";

export type FreeMcModCatalogEntry = {
  /** Modrinth project slug — passed verbatim into MODRINTH_PROJECTS. */
  slug: string;
  label: string;
  description: string;
  category: FreeMcModCategory;
};

export const FREEMC_MOD_CATALOG: FreeMcModCatalogEntry[] = [
  // ---- Economy ----
  {
    slug: "ultimateshop",
    label: "UltimateShop",
    description: "A ready-to-use buy/sell GUI shop with its own built-in economy — no other economy plugin required.",
    category: "Economy",
  },

  // ---- Protection / Anti-grief ----
  {
    slug: "coreprotect",
    label: "CoreProtect",
    description: "Logs every block change and lets you roll back grief or accidents to a specific time — the standard anti-grief safety net.",
    category: "Protection",
  },
  {
    slug: "griefprevention",
    label: "GriefPrevention",
    description: "Players claim land with a golden shovel to stop others building, breaking, or stealing there.",
    category: "Protection",
  },

  // ---- Utility / QoL ----
  {
    slug: "placeholderapi",
    label: "PlaceholderAPI",
    description: "A shared library of dynamic text placeholders (player stats, time, world info) that other plugins on this list hook into automatically.",
    category: "Utility",
  },
  {
    slug: "deluxemenus",
    label: "DeluxeMenus",
    description: "Build custom clickable GUI menus (server info, warps, rules) from a config file — no coding required.",
    category: "Utility",
  },
  {
    slug: "multiverse-core",
    label: "Multiverse-Core",
    description: "Create and manage extra worlds alongside your main one, each with its own settings.",
    category: "Utility",
  },
  {
    slug: "chunky",
    label: "Chunky",
    description: "Pregenerates world chunks ahead of time so players don't hit generation lag exploring new terrain.",
    category: "Utility",
  },
  {
    slug: "skinsrestorer",
    label: "SkinsRestorer",
    description: "Restores real player skins even though this server runs in offline mode — otherwise everyone shows as Steve/Alex.",
    category: "Utility",
  },
  {
    slug: "pwarps",
    label: "Player Warps",
    description: "Lets players set and share their own named warp points.",
    category: "Utility",
  },
  {
    slug: "axgraves",
    label: "AxGraves",
    description: "Drops a player's items into a protected grave on death instead of scattering on the ground, so only they (or their group) can collect it back.",
    category: "Utility",
  },
  {
    slug: "playerkits-2",
    label: "PlayerKits 2",
    description: "Configurable /kit menu — starter gear, timed rebuys, and permission-gated kits.",
    category: "Utility",
  },

  // ---- Fun / Cosmetic ----
  {
    slug: "ultracosmetics",
    label: "UltraCosmetics",
    description: "Unlockable cosmetic gadgets, particle trails, and effects for players to show off with — purely cosmetic, no gameplay impact.",
    category: "Fun",
  },
  {
    slug: "player-heads",
    label: "Player Heads",
    description: "Mobs and players drop their own head as a collectible/decoration item on death.",
    category: "Fun",
  },
  {
    slug: "namecolor",
    label: "Name Color",
    description: "Lets players recolor their own name and chat text with a simple command.",
    category: "Fun",
  },

  // ---- Admin / Moderation ----
  {
    slug: "discordsrv",
    label: "DiscordSRV",
    description: "Links server chat with a Discord channel and posts join/leave/death messages there. Needs a bot token added to its config after install to actually connect — it stays inactive (and your server keeps running fine) until you do.",
    category: "Admin",
  },
  {
    slug: "maintenance",
    label: "Maintenance",
    description: "Lock the server behind a maintenance screen for everyone except operators — handy while you're mid-change.",
    category: "Admin",
  },
];

"use server";

/**
 * Mod Menu action: lets a free-tier Minecraft owner layer EXTRA vetted
 * plugins (lib/freemc-mod-catalog.ts) on top of whatever their active preset
 * already bundles. Follows the exact same container-recreate discipline as
 * applyFreeMinecraftPreset in lib/actions-free-minecraft.ts: docker rm -f the
 * old container, docker run -d the new one, sleep 15s, then docker inspect to
 * confirm it's still alive before trusting it — `docker run -d`'s own exit
 * code only means the process started, not that it survived an init-time
 * plugin failure. On failure this rolls back to the account's PREVIOUS
 * extraMods list rather than leaving the customer with a dead server, and
 * `extraMods` is only ever persisted on the DB row once the new container is
 * confirmed running.
 *
 * Deliberately a separate file/module from lib/actions-free-minecraft.ts (per
 * this feature's isolation requirement) rather than reusing its private
 * `recreatePresetContainer`/`freemcHost` helpers, which aren't exported — the
 * container-run command below is kept in lock-step with that function's
 * shape on purpose; if that file's recreate logic changes, this should be
 * updated to match.
 */
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { checkRateLimit } from "./rate-limit";
import { getSetting, getSettingInt } from "./settings";
import { withServerSsh, exec, shellQuote } from "./ssh-exec";
import type { SftpServer } from "./sftp";
import {
  rconPasswordFor,
  propertiesToEnv,
  FREEMC_PRESETS,
  FREEMC_PLUGIN_MC_VERSION,
  type FreeMcPreset,
} from "./free-minecraft-control";
import { FREEMC_MOD_CATALOG } from "./freemc-mod-catalog";

type Result = { error?: string };

const CATALOG_SLUGS = new Set(FREEMC_MOD_CATALOG.map((m) => m.slug));

/** Same target as lib/actions-free-minecraft.ts's freemcHost() — that helper
 *  isn't exported, so this is a deliberate, identical duplicate rather than a
 *  cross-file import, per this feature's file-isolation requirement. */
async function freemcHost(): Promise<SftpServer> {
  const host = await db.server.findFirst({
    where: { hostname: "freemc-host" },
    select: { id: true, rootPassword: true, rootPasswordEnc: true, sshPort: true, dedicatedIp: { select: { address: true } } },
  });
  if (!host) throw new Error("Free Minecraft host is not provisioned.");
  return host;
}

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

/**
 * Recreates the free server's container for `preset`, with `extraModSlugs`
 * merged into MODRINTH_PROJECTS on top of whatever the preset itself already
 * declares, and verifies it's still alive ~15s later — identical health-check
 * timing/shape to recreatePresetContainer in lib/actions-free-minecraft.ts.
 * Never throws; the caller decides what a failure means.
 */
async function recreateWithMods(
  conn: import("ssh2").Client,
  row: { id: string; containerName: string; subdomain: string },
  preset: FreeMcPreset,
  extraModSlugs: string[],
  userId: string,
  domain: string,
  ramMb: number,
): Promise<{ ok: boolean; error?: string }> {
  const jvmRatio = 0.7; // this action only ever runs against kind:"plugins" presets
  const jvmMb = Math.max(256, Math.round(ramMb * jvmRatio));

  const baseEnv = { ...propertiesToEnv(preset.properties), ...(preset.env ?? {}) };
  const presetSlugs = (baseEnv.MODRINTH_PROJECTS ?? "")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
  const mergedSlugs = [...new Set([...presetSlugs, ...extraModSlugs])];
  const envVars = { ...baseEnv, MODRINTH_PROJECTS: mergedSlugs.join(",") };

  const envFlags = Object.entries(envVars)
    .map(([k, v]) => `-e ${k}=${shellQuote(v)}`)
    .join(" ");

  await exec(conn, `docker rm -f ${shellQuote(row.containerName)}`, 30_000);
  // Clear old plugin jars first — same reasoning as applyFreeMinecraftPreset:
  // MODRINTH_PROJECTS only ADDS/updates what it lists, it never prunes a jar
  // that's no longer listed, so a mod the owner just REMOVED would otherwise
  // keep running.
  await exec(conn, `rm -rf ${shellQuote(`/opt/freemc/servers/${row.id}/plugins`)}`, 15_000).catch(() => {});
  const cmd = [
    "docker run -d",
    `--name ${shellQuote(row.containerName)}`,
    "--network freemc",
    `--memory=${ramMb}m --memory-swap=${ramMb}m --cpus=1`,
    `--label mc-router.host=${shellQuote(`${row.subdomain}.${domain}`)}`,
    `-v ${shellQuote(`/opt/freemc/servers/${row.id}`)}:/data`,
    `-e EULA=TRUE -e TYPE=${preset.type ?? "PAPER"} -e ONLINE_MODE=FALSE`,
    `-e VERSION=${shellQuote(FREEMC_PLUGIN_MC_VERSION)}`,
    `-e MEMORY=${jvmMb}m`,
    `-e ENABLE_RCON=true -e RCON_PASSWORD=${shellQuote(rconPasswordFor(userId))}`,
    envFlags,
    "itzg/minecraft-server",
  ].join(" ");
  const run = await exec(conn, cmd, 90_000);
  if (run.code !== 0) return { ok: false, error: run.stderr || "docker run failed" };

  await sleep(15_000);
  const check = await exec(conn, `docker inspect -f '{{.State.Running}}' ${shellQuote(row.containerName)}`, 10_000);
  if (check.code !== 0 || check.stdout.trim() !== "true") {
    return { ok: false, error: "Container exited shortly after starting." };
  }
  return { ok: true };
}

export async function applyFreeMinecraftMods(_prev: unknown, formData: FormData): Promise<Result> {
  const user = await requireUser();
  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
  if (!row) return { error: "You don't have a free server." };

  const preset = FREEMC_PRESETS[row.preset];
  if (!preset || preset.kind !== "plugins") {
    return { error: "Your current game mode doesn't run plugins, so there's nothing for extra mods to install into. Switch to a plugin-based preset first." };
  }

  const rl = checkRateLimit(`freemc:mods:${user.id}`, { max: 10, windowMs: 60_000 });
  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };

  const submitted = formData.getAll("mods").map((v) => String(v));
  const invalid = submitted.filter((s) => !CATALOG_SLUGS.has(s));
  if (invalid.length > 0) {
    return { error: "One or more selected mods aren't recognized — please refresh and try again." };
  }
  const selected = [...new Set(submitted)];

  const domain = await getSetting("free_minecraft_domain", "play.nxeon.cloud");
  const ramMb = await getSettingInt("free_minecraft_ram_mb", 1024);
  const previousMods = row.extraMods;

  try {
    const host = await freemcHost();
    const outcome = await withServerSsh(host, async (conn) => {
      const applied = await recreateWithMods(conn, row, preset, selected, user.id, domain, ramMb);
      if (applied.ok) return { ok: true as const };

      console.error("[freemc-mods] apply failed, rolling back:", applied.error);
      const rolledBack = await recreateWithMods(conn, row, preset, previousMods, user.id, domain, ramMb);
      return rolledBack.ok
        ? { ok: false as const, error: "That mod selection didn't start cleanly, so we put your server back the way it was." }
        : { ok: false as const, error: "That mod selection didn't start, and restoring your previous setup also failed — please contact support." };
    });
    if (!outcome.ok) return { error: outcome.error };
  } catch (e) {
    console.error("[freemc-mods] apply failed:", e);
    return { error: "Couldn't apply your mod selection — please try again." };
  }

  await db.freeMinecraftServer.update({ where: { id: row.id }, data: { extraMods: selected } });
  revalidatePath("/dashboard/free-minecraft");
  return {};
}

"use client";

/**
 * Mod Menu tab: lets the owner layer extra vetted plugins (from the fixed
 * catalog in lib/freemc-mod-catalog.ts) on top of whatever their active
 * preset already bundles. Mirrors the visual language of the other
 * FreeMcDashboard tabs (Overview/Settings) — card container, grouped
 * sections, btn-primary submit — see components/customer/freemc/
 * FreeMcDashboard.tsx for the reference styling this matches.
 *
 * Not wired into FreeMcDashboard.tsx yet (deliberately, per this feature's
 * file-isolation requirement) — drop `<ModsTab server={...} />` in as a new
 * tab there whenever this is integrated.
 */
import { useActionState, useMemo, useState } from "react";
import { applyFreeMinecraftMods } from "@/lib/actions-freemc-mods";
import { FREEMC_MOD_CATALOG, type FreeMcModCategory } from "@/lib/freemc-mod-catalog";
import { FREEMC_PRESETS } from "@/lib/free-minecraft-control";

const CATEGORY_ORDER: FreeMcModCategory[] = ["Economy", "Protection", "Utility", "Fun", "Admin"];
const CATEGORY_LABEL: Record<FreeMcModCategory, string> = {
  Economy: "Economy",
  Protection: "Protection / Anti-grief",
  Utility: "Utility / QoL",
  Fun: "Fun / Cosmetic",
  Admin: "Admin / Moderation",
};

export function ModsTab({ server }: { server: { preset: string; extraMods: string[] } }) {
  const preset = FREEMC_PRESETS[server.preset];
  const runsPlugins = preset?.kind === "plugins";

  const [selected, setSelected] = useState<Set<string>>(() => new Set(server.extraMods));
  const [state, action, pending] = useActionState(applyFreeMinecraftMods, {});

  const grouped = useMemo(() => {
    const byCategory = new Map<FreeMcModCategory, typeof FREEMC_MOD_CATALOG>();
    for (const cat of CATEGORY_ORDER) byCategory.set(cat, []);
    for (const mod of FREEMC_MOD_CATALOG) byCategory.get(mod.category)!.push(mod);
    return byCategory;
  }, []);

  function toggle(slug: string) {
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(slug)) next.delete(slug);
      else next.add(slug);
      return next;
    });
  }

  const dirty =
    selected.size !== server.extraMods.length || [...selected].some((s) => !server.extraMods.includes(s));

  return (
    <div className="card">
      <h3 className="font-semibold text-[var(--fg)]">Mod menu</h3>
      <p className="mt-1 text-sm text-slate-400">
        Add extra plugins on top of your current preset, picked from a curated, pre-tested list — never free text.
        Saving restarts your server while the new plugins install.
      </p>

      {!runsPlugins ? (
        <div className="mt-4 rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-sm text-amber-300">
          Your current game mode ({preset?.label ?? server.preset}) doesn&apos;t run plugins, so there&apos;s nowhere for
          extra mods to install into. Switch to a plugin-based preset in Overview first (SkyBlock, Prison, Towny,
          Parkour, Anarchy, Lifesteal SMP, Missile Wars, or Survival Games).
        </div>
      ) : (
        <form action={action} className="mt-4 space-y-6">
          {state.error && (
            <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">{state.error}</div>
          )}
          {CATEGORY_ORDER.map((cat) => {
            const mods = grouped.get(cat) ?? [];
            if (mods.length === 0) return null;
            return (
              <div key={cat}>
                <h4 className="text-sm font-semibold text-[var(--fg)]">{CATEGORY_LABEL[cat]}</h4>
                <div className="mt-2 grid gap-2 sm:grid-cols-2">
                  {mods.map((mod) => (
                    <label
                      key={mod.slug}
                      className={`flex cursor-pointer flex-col gap-1 rounded-xl border px-3 py-2.5 text-sm transition-colors ${
                        selected.has(mod.slug) ? "border-brand-400/50 bg-brand-500/10" : "border-white/[0.08] hover:border-white/20"
                      }`}
                    >
                      <div className="flex items-center gap-2">
                        <input
                          type="checkbox"
                          name="mods"
                          value={mod.slug}
                          checked={selected.has(mod.slug)}
                          onChange={() => toggle(mod.slug)}
                          className="h-4 w-4 rounded border-white/20 bg-transparent"
                        />
                        <span className="font-medium text-[var(--fg)]">{mod.label}</span>
                      </div>
                      <span className="pl-6 text-xs text-slate-500">{mod.description}</span>
                    </label>
                  ))}
                </div>
              </div>
            );
          })}

          <div className="flex items-center gap-3">
            <button className="btn-primary text-sm" disabled={pending || !dirty}>
              {pending ? "Applying…" : "Save & restart"}
            </button>
            {!dirty && <span className="text-xs text-slate-500">No changes to save.</span>}
          </div>
          <p className="text-xs text-slate-500">
            Saving restarts your server to install (or remove) the selected mods consistently.
          </p>
        </form>
      )}
    </div>
  );
}
